export interface Stream<A> {
  pipe<B>(...stages: ReadonlyArray<(stream: Stream<A>) => Stream<B>>): Stream<B>
}

export declare const fromReadableStream: <A, E>(options: {
  readonly evaluate: () => ReadableStream<A>
  readonly onError: (error: unknown) => E
}) => Stream<A>

export declare const map: <A, B>(f: (chunk: A) => B) => (stream: Stream<A>) => Stream<B>
